WITH RECURSIVE x9 AS (SELECT RANK() OVER (ORDER BY x7.SUBSTRING_INDEX('aaaaaaaaa1', '1', 1)) AS x10 UNION SELECT CAST('2006-09-26' AS DATE) + INTERVAL '1' DAY FROM x11 WHERE x7.Name_exp_7 < 10) SELECT x7.SUBSTRING_INDEX('aaaaaaaaa1', '1', 1), x7.SUBSTRING_INDEX('aaaaaaaaa1', '1', 1), ST_TOUCHES(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION()'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x4, x7.SUBSTRING_INDEX('aaaaaaaaa1', '1', 1) FROM v113258 AS x7 WHERE x7.SUBSTRING_INDEX('aaaaaaaaa1', '1', 1) BETWEEN 0.0 AND 0.4